    """Check if a square is attacked by the given side."""
    # Temporarily change side to move to attacking side
    original_side = 'w' if attacking_side == 'w' else 'b'

    # Check if any piece of the attacking side can move to this square
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if piece is None:
                continue

            is_white = piece.isupper()
            if (is_white and original_side != 'w') or (not is_white and original_side != 'b'):
